async def act(page):
    import re, asyncio

    # The exact article title we're trying to find
    title = "Jimmy Kimmel takes aim at Trump in ‘alternative Christmas message’ to UK"

    # Defensive: dismiss any blocking dialog/pop-up if present
    dialog_locator = page.get_by_role("dialog")
    if await dialog_locator.count() > 0:
        # click the first button inside the dialog (commonly a close control)
        dialog_buttons = dialog_locator.get_by_role("button")
        if await dialog_buttons.count() > 0:
            try:
                await dialog_buttons.first.click()
                await asyncio.sleep(0.5)
            except Exception:
                # If clicking the dialog button fails, try pressing Escape as a fallback
                try:
                    await page.keyboard.press("Escape")
                    await asyncio.sleep(0.5)
                except Exception:
                    pass

    # Locate the complementary region (sidebar) that contains the search widget
    comp_locator = page.get_by_role("complementary")
    if await comp_locator.count() == 0:
        # Nothing we can do if complementary region is missing; return empty
        print([])
        return []
    comp = comp_locator.first

    # Prefer a role=searchbox named "Search" inside the complementary region
    searchbox_locator = comp.get_by_role("searchbox", name="Search")
    if await searchbox_locator.count() == 0:
        # Fallback to a generic textbox inside the complementary region
        textbox_locator = comp.get_by_role("textbox")
        if await textbox_locator.count() == 0:
            # No search input available
            print([])
            return []
        searchbox = textbox_locator.first
    else:
        searchbox = searchbox_locator.first

    # Fill the search input with the exact title
    await searchbox.fill(title)

    # Try to activate the visible Search button inside the complementary region (full path)
    search_button_locator = comp.get_by_role("button", name=re.compile(r"search", re.IGNORECASE))
    if await search_button_locator.count() > 0:
        try:
            await search_button_locator.first.click()
        except Exception:
            # If clicking the button fails (sometimes overlays intercept clicks), press Enter in the input as a fallback
            try:
                await searchbox.press("Enter")
            except Exception:
                pass
    else:
        # No explicit button found; press Enter in the search input
        try:
            await searchbox.press("Enter")
        except Exception:
            pass

    # Wait for results to render: prefer main region becoming available
    try:
        await page.get_by_role("main").wait_for(timeout=5000)
    except Exception:
        # Fallback to network idle wait
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    # Scrape role=article entries inside the main region and look for a title match
    main_locator = page.get_by_role("main")
    if await main_locator.count() == 0:
        print([])
        return []
    main = main_locator.first

    articles = main.get_by_role("article")
    article_count = await articles.count()

    for i in range(article_count):
        art = articles.nth(i)
        # Prefer heading -> link pattern
        heading_locator = art.get_by_role("heading")
        link_candidate = None
        if await heading_locator.count() > 0:
            heading = heading_locator.first
            heading_links = heading.get_by_role("link")
            if await heading_links.count() > 0:
                link_candidate = heading_links.first
        if link_candidate is None:
            # Fallback to the first link inside the article
            article_links = art.get_by_role("link")
            if await article_links.count() > 0:
                link_candidate = article_links.first

        if link_candidate is None:
            continue

        try:
            link_text = (await link_candidate.inner_text()).strip()
        except Exception:
            link_text = ""
        try:
            href = await link_candidate.get_attribute("href")
        except Exception:
            href = None

        if title.lower() in link_text.lower():
            # Found the article. Return the raw result as a list-of-dicts (title/url) and print it
            result = [{"title": link_text, "url": href}]
            print(result)
            return result

    # If we reach here, no matching article was found in the results
    print([])
    return []

